\", \"symbol\": \"volume\", \"type\": \"Lebesgue measure on the real line\", \"definition\": \"volume denotes Lebesgue measure on the Borel measurable space ℝ, with values in ℝ≥0∞.\", \"depends_on\": [], \"requires\": [], \"binders\": [], \"objects\": []}, {\"id\": \"D018\", \"symbol\": \"indicator\", \"type\": \"set indicator with a zero outside branch\", \"definition\": \"For a set B⊆W and function f:W→ℝ≥0∞, indicator(B,f)(t)=f(t) for t∈B and 0 otherwise. We write 1_B(t)c for indicator(B,constant c)(t), including c=∞; this uses a zero branch outside B.\", \"depends_on\": [], \"requires\": [], \"binders\": [{\"symbol\": \"W\", \"type\": \"type\"}, {\"symbol\": \"B\", \"type\": \"subset of W\"}, {\"symbol\": \"f\", \"type\": \"function W→ℝ≥0∞\"}, {\"symbol\": \"t\", \"type\": \"point of W\"}, {\"symbol\": \"c\", \"type\": \"extended nonnegative constant\"}], \"objects\": [\"W\", \"B\", \"f\", \"t\", \"c\"]}, {\"id\": \"D019\", \"symbol\": \"lintegral\", \"type\": \"nonnegative lower integral\", \"definition\": \"lintegral(μ,f)=∫⁻ t,f(t)∂μ is the supremum of the integrals of nonnegative measurable simple functions below f, for a measure μ on a measurable space W and f:W→ℝ≥0∞. No finiteness of the value is implicit.\", \"depends_on\": [], \"requires\": [], \"binders\": [{\"symbol\": \"W\", \"type\": \"measurable space\"}, {\"symbol\": \"μ\", \"type\": \"measure on W\"}, {\"symbol\": \"f\", \"type\": \"function W→ℝ≥0∞\"}, {\"symbol\": \"t\", \"type\": \"point of W\"}], \"objects\": [\"W\", \"μ\", \"f\", \"t\"]}], \"logic\": {\"classical\": true, \"rules\": [\"direct\", \"forall_introduction\", \"implication_introduction\", \"exists_elimination\", \"case_elimination\", \"contradiction_classical\"], \"calculations\": [\"equality\", \"definitions\", \"finite_algebra\", \"finite_order\", \"finite_sums\"], \"primitives\": [{\"symbol\": \"0\", \"type\": \"typed numeral\", \"meaning\": \"Zero of the explicitly specified mathematical type.\"}, {\"symbol\": \"1\", \"type\": \"typed numeral\", \"meaning\": \"One of the explicitly specified mathematical type.\"}, {\"symbol\": \"2\", \"type\": \"typed numeral\", \"meaning\": \"Two of the explicitly specified mathematical type, including an exponent two.\"}, {\"symbol\": \"ℕ\", \"type\": \"number system\", \"meaning\": \"The natural numbers with their usual arithmetic.\"}, {\"symbol\": \"ℤ\", \"type\": \"number system\", \"meaning\": \"The integers with their usual arithmetic.\"}, {\"symbol\": \"ℚ\", \"type\": \"number system\", \"meaning\": \"The rational numbers with their usual ordered-field operations.\"}, {\"symbol\": \"ℝ\", \"type\": \"number system\", \"meaning\": \"The real numbers with their usual ordered-field structure.\"}, {\"symbol\": \"ℂ\", \"type\": \"number system\", \"meaning\": \"The complex numbers with their usual field structure.\"}, {\"symbol\": \"∅\", \"type\": \"typed set notation\", \"meaning\": \"The empty set in the explicitly specified ambient type.\"}, {\"symbol\": \"∞\", \"type\": \"typed order notation\", \"meaning\": \"The top element in an explicitly specified extended ordered codomain.\"}]}, \"pins\": {\"lean_version\": \"4.32.2\", \"mathlib_commit\": \"905b95818eb32af7874a58b427f50c1711a5e96c\", \"mathlib_root\": \"/Users/syyui/formalization-tools/lean-mathlib-v4.32.2/mathlib\"}, \"inputs\": [{\"path\": \"inputs/basis-evidence-000.txt\", \"sha256\": \"56242fc597019e658c0e8792098ddb686d913156e0d831a14366d114cbf743f0\"}, {\"path\": \"inputs/basis-evidence-001.txt\", \"sha256\": \"dc2269f5e00938d87aaee97208ff318220f264dee5c5fe78307c2fc6ced8d8b6\"}, {\"path\": \"inputs/basis-proof.md\", \"sha256\": \"3c6c4c0b0c0522e740340ae8570f46709b577a523cbf33d3739a75ae4e15621b\"}, {\"path\": \"inputs/basis-registry.json\", \"sha256\": \"94cca4691b7a0d149adb23a24a120461be1a8e2eefb2f1daba11ffb1e138bfdd\"}, {\"path\": \"inputs/problem.md\", \"sha256\": \"56242fc597019e658c0e8792098ddb686d913156e0d831a14366d114cbf743f0\"}, {\"path\": \"inputs/proof-context.json\", \"sha256\": \"